import {Effect, Either, Schedule, Schema} from 'effect';
import {orient, scout, goTo, mine, sell, service, prices, readMarket, salvage, hunt, disengage,
  missions, acceptMission, completeMissions, note, MarketBook} from 'play';

export default Effect.gen(function* () {
  const [here, raw] = yield* Effect.all([orient(), readMarket()], {concurrency: 'unbounded'});

  const book = yield* Schema.decodeUnknown(MarketBook)(raw);
  if (Either.isLeft(book)) {
    yield* note('bad book');
    return;
  }

  const buyByItem = new Map<string, number>(
    book.rows.map(r => [r.item_id, r.best_buy] as [string, number])
  );

  const toSell = here.cargo
    .filter(r => (buyByItem.get(r.item_id) ?? 0) >= 10)
    .map(r => ({item_id: r.item_id}));

  if (toSell.length > 0) {
    yield* sell(toSell);
  }
}).pipe(Effect.catchTag('ParseError', () => Effect.zipRight(note('bad book'), Effect.void)));
