import {Effect, Either, Schedule, Schema} from 'effect';
import {
  orient,
  scout,
  goTo,
  mine,
  sell,
  service,
  prices,
  readMarket,
  salvage,
  hunt,
  disengage,
  missions,
  acceptMission,
  completeMissions,
  note,
  MarketBook,
} from 'play';

export default Effect.gen(function* () {
  const board = yield* missions();

  let accepted = 0;
  for (const m of board) {
    if (m.reward < 100) continue;
    const step = yield* acceptMission(m.id).pipe(Effect.either);
    if (Either.isLeft(step)) {
      if (step.left._tag === 'NoSlots') break;
      return yield* Effect.fail(step.left);
    }
    accepted++;
  }

  const complete = yield* completeMissions().pipe(Effect.either);
  if (Either.isLeft(complete)) {
    if (complete.left._tag === 'NothingCompletable') {
      yield* note('Nothing to complete at this base');
    } else {
      return yield* Effect.fail(complete.left);
    }
  }

  return accepted;
});
