import {Effect, Either, Schedule, Schema} from 'effect';
import {orient, scout, goTo, mine, sell, service, prices, readMarket, salvage, hunt, disengage,
  missions, acceptMission, completeMissions, note, MarketBook} from 'play';

export default Effect.gen(function* () {
  const here = yield* goTo('kepler_belt');

  // Mine until the hold is full; disengage and keep going if pirates engage.
  while (true) {
    const step = yield* mine().pipe(Effect.either);
    if (Either.isRight(step)) continue;
    if (step.left._tag === 'HoldFull') break;
    if (step.left._tag === 'InBattle') {
      yield* disengage();
      continue;
    }
    return yield* Effect.fail(step.left);
  }

  yield* goTo('kepler_base');
  yield* sell([{item_id: 'copper_ore'}]);
  yield* service();
  yield* completeMissions().pipe(Effect.catchTag('NothingCompletable', () => note('nothing to turn in')));

  const done = yield* orient();
  yield* note(`now at ${done.credits} credits`);
  return done;
}).pipe(Effect.ensuring(Effect.gen(function* () {
  const s = yield* orient();
  return yield* note(`final: ${s.credits} credits`);
})));
