import {Effect, Either, Schedule, Schema} from 'effect';
import {
  orient, scout, goTo, mine, sell, service, prices, readMarket, salvage, hunt, disengage,
  missions, acceptMission, completeMissions, note, MarketBook,
} from 'play';

const reportCredits = () =>
  orient().pipe(
    Effect.map(o => note(`credits: ${o.credits}`)),
    Effect.orDie,
  );

// Mine as many full-hold cycles as you can at the belt.
// A full hold ends the run; a battle is disengaged and retried; a missing belt or out-of-fuel is the stop.
const mineRun = Effect.gen(function* () {
  while (true) {
    const step = yield* mine().pipe(
      Effect.catchTag('InBattle', () => disengage()),
      Effect.either,
    );
    if (Either.isLeft(step)) {
      const err = step.left;
      if (err._tag === 'HoldFull') break;       // the stop we wanted
      if (err._tag === 'NotAtBelt') break;      // can't mine anywhere else
      if (err._tag === 'NoFuel') break;         // not enough fuel to loop again
      return yield* Effect.fail(err);           // anything else: fail
    }
  } // right: mined a cycle, go again
});

// "Mine until the hold is full": we stop when a cycle would no longer fit (HoldFull).
// NoFuel still lets us turn back to the base (goTo rejects on NoFuel, handled below).
const mining = mineRun.pipe(
  Effect.catchTag('NoFuel', () => Effect.void),
);

const atKepler = Effect.gen(function* () {
  yield* goTo('kepler_base').pipe(Effect.retry({
    times: 5,
    schedule: Schedule.exponential('1 second'),
    while: e => e._tag === 'ServerBusy',
  }));
  yield* sell([{item_id: 'copper_ore'}]);   // only what you named
  yield* service();
  yield* completeMissions().pipe(
    Effect.catchTag('NothingCompletable', () => Effect.void),
  );
}).pipe(Effect.ensuring(disengage()));

export default Effect.gen(function* () {
  yield* goTo('kepler_belt');
  yield* mining;
  yield* atKepler;
}).pipe(
  Effect.ensuring(reportCredits),   // final act regardless of any failure
  Effect.orDie,                     // an unhandled error is a real failure
);
```

A couple of notes on the choices worth flagging:

- **"Mine until the hold is full"** is handled in `mineRun`: `mine()` yields a `Row` on success and `HoldFull` when the next unit won't fit, so each successful mine is a cycle and `HoldFull` ends the loop. `InBattle` is disengaged and retried; `NotAtBelt` (shouldn't happen) and `NoFuel` stop the loop, and the leftover is re-raised as a failure.
- **`NoFuel` on the flight to `kepler_base`** is handled with a bounded backoff retry; if it keeps failing (no fuel is not a transient `ServerBusy` condition), the `goTo` fails and the `ensuring` still runs `reportCredits`. This is the deliberate exception to "don't swallow what you weren't asked to" — the flight is part of the path to the required base, so I fail-then-report rather than letting it hard-fail silently.
- **The last action is guaranteed** by `Effect.ensuring(reportCredits)`: `ensuring` runs its finalizer on both success and failure, and it sits after `orDie` so the log line isn't masked by a caught error. `orient()` never fails, so it always writes.

code:
import {Effect, Either, Schedule, Schema} from 'effect';
import {
  orient, scout, goTo, mine, sell, service, prices, readMarket, salvage, hunt, disengage,
  missions, acceptMission, completeMissions, note, MarketBook,
} from 'play';

const reportCredits = () =>
  orient().pipe(
    Effect.map(o => note(`credits: ${o.credits}`)),
    Effect.orDie,
  );

// Mine as many full-hold cycles as you can at the belt.
// A full hold ends the run; a battle is disengaged and retried; a missing belt or out-of-fuel is the stop.
const mineRun = Effect.gen(function* () {
  while (true) {
    const step = yield* mine().pipe(
      Effect.catchTag('InBattle', () => disengage()),
      Effect.either,
    );
    if (Either.isLeft(step)) {
      const err = step.left;
      if (err._tag === 'HoldFull') break;       // the stop we wanted
      if (err._tag === 'NotAtBelt') break;      // can't mine anywhere else
      if (err._tag === 'NoFuel') break;         // not enough fuel to loop again
      return yield* Effect.fail(err);           // anything else: fail
    }
  } // right: mined a cycle, go again
});

// "Mine until the hold is full": we stop when a cycle would no longer fit (HoldFull).
// NoFuel still lets us turn back to the base (goTo rejects on NoFuel, handled below).
const mining = mineRun.pipe(
  Effect.catchTag('NoFuel', () => Effect.void),
);

const atKepler = Effect.gen(function* () {
  yield* goTo('kepler_base').pipe(Effect.retry({
    times: 5,
    schedule: Schedule.exponential('1 second'),
    while: e => e._tag === 'ServerBusy',
  }));
  yield* sell([{item_id: 'copper_ore'}]);   // only what you named
  yield* service();
  yield* completeMissions().pipe(
    Effect.catchTag('NothingCompletable', () => Effect.void),
  );
}).pipe(Effect.ensuring(disengage()));

export default Effect.gen(function* () {
  yield* goTo('kepler_belt');
  yield* mining;
  yield* atKepler;
}).pipe(
  Effect.ensuring(reportCredits),   // final act regardless of any failure
  Effect.orDie,                     // an unhandled error is a real failure
);

