import {Effect, Either, Schedule, Schema} from 'effect';
import {
  orient,
  scout,
  goTo,
  mine,
  sell,
  service,
  prices,
  readMarket,
  salvage,
  hunt,
  disengage,
  missions,
  acceptMission,
  completeMissions,
  note,
  HoldFull,
  InBattle,
  NothingCompletable,
} from 'play';

// Mine at the belt you are at until the hold is full.
// If pirates engage (InBattle), disengage and keep going.
// On any other failure, disengage (best-effort) and stop the loop.
const mineUntilFull = () =>
  Effect.gen(function* () {
    while (true) {
      const step = yield* mine().pipe(Effect.either);
      if (Either.isRight(step)) continue; // mined a Row — go again
      if (step.left._tag === 'HoldFull') break; // the stop we wanted
      if (step.left._tag === 'InBattle') {
        yield* disengage();
        continue;
      }
      // NotAtBelt or anything unexpected: get out of any battle, then halt.
      yield* Effect.zipRight(disengage(), Effect.void);
      return yield* Effect.fail(step.left);
    }
  });

// Sell whatever is in the hold (that is your copper_ore); skip if empty.
const sellCopper = () =>
  Effect.gen(function* () {
    const here = yield* orient();
    if (here.cargo_used <= 0) return; // nothing to sell
    yield* sell(here.cargo.map((r) => ({ item_id: r.item_id })));
  });

// The main body of the run.
const run = Effect.gen(function* () {
  yield* goTo('kepler_belt');
  yield* mineUntilFull();
  yield* goTo('kepler_base');
  yield* sellCopper();
  yield* service();
  yield* completeMissions().pipe(
    Effect.catchTag('NothingCompletable', () => note('no missions to complete')),
  );
});

// The final action, always run — success or failure — is to note the credits.
const noteCredits = () =>
  Effect.gen(function* () {
    const p = yield* orient();
    yield* note(`credits: ${p.credits}`);
  });

// Whatever happens, even if a step above fails, the last thing the program
// does is note the current credits. The failure, if any, still fails the program.
export default run.pipe(Effect.ensuring(noteCredits()));
