import {Effect, Either, Schedule, Schema} from 'effect';
import {orient, scout, goTo, mine, sell, service, prices, readMarket, salvage, hunt, disengage,
  missions, acceptMission, completeMissions, note, MarketBook} from 'play';

export default Effect.gen(function* () {
  // Mine repeatedly until the hold is full.
  while (true) {
    const step = yield* mine().pipe(Effect.either);
    if (Either.isRight(step)) continue;               // mined another cycle; go again
    if (step.left._tag === 'HoldFull') break;         // the stop we wanted
    if (step.left._tag === 'InBattle') {
      yield* disengage();
      continue;                                       // interrupted; keep going after we leave
    }
    return yield* Effect.fail(step.left);             // anything else (NotAtBelt): fail with it
  }

  // Fly back to base and dock.
  yield* goTo('sol_base');

  // Sell everything in the hold, every item (omit quantity = all of it).
  const here = yield* orient();
  const sold = yield* sell(here.cargo.map(r => ({item_id: r.item_id})));
  yield* note(`sold for ${sold.total}`);
});
