import {Effect, Either, Schedule, Schema} from 'effect';
import {orient, scout, goTo, mine, sell, service, prices, readMarket, salvage, hunt, disengage,
  missions, acceptMission, completeMissions, note, MarketBook} from 'play';

export default Effect.gen(function* () {
  const raw = yield* readMarket();
  const decoded = yield* Schema.decodeUnknown(MarketBook)(raw).pipe(Effect.either);

  if (Either.isLeft(decoded)) {
    yield* note('bad book');
    return;
  }

  const book = decoded.right;
  const bestBuy = new Map<string, number>();
  for (const row of book.rows) bestBuy.set(row.item_id, row.best_buy);

  const here = yield* orient();
  const toSell = here.cargo.filter(r => (bestBuy.get(r.item_id) ?? 0) >= 10)
    .map(r => ({item_id: r.item_id}));

  if (toSell.length > 0) {
    const sold = yield* sell(toSell);
    yield* note(`sold ${sold.total} credits`);
  }
});
