import {Effect, Either, Schedule, Schema} from 'effect';
import {orient, scout, goTo, mine, sell, service, prices, readMarket, salvage, hunt, disengage,
  missions, acceptMission, completeMissions, note, MarketBook} from 'play';

export default Effect.gen(function* () {
  const board = yield* missions();
  let accepted = 0;
  for (const m of board) {
    if (m.reward < 100) continue;
    const step = yield* acceptMission(m.id).pipe(Effect.either);
    if (Either.isRight(step)) {
      accepted++;
    } else if (step.left._tag === 'NoSlots') {
      break;
    } else {
      return yield* Effect.fail(step.left);
    }
  }

  const done = yield* completeMissions().pipe(Effect.either);
  if (Either.isLeft(done) && done.left._tag === 'NothingCompletable') {
    yield* note('nothing completable');
  }

  return accepted;
});
