import {Effect} from 'effect';
import {orient, goTo, mine, sell, service, completeMissions, disengage, note} from 'play';

// One cycle at the belt: if pirates engage, disengage and keep trying;
// the only time we stop is when the hold is full.
const mineUntilFull = () =>
  Effect.gen(function* () {
    const res = yield* mine().pipe(Effect.either);
    if (res._tag === 'Right') return;
    switch (res.left._tag) {
      case 'InBattle':
        yield* disengage();
        break;
      case 'HoldFull':
        return;
    }
    return yield* Effect.fail(res.left);
  });

// Mined and the hold full. flyTo + sell do not fail with InBattle.
const haulCycle = () =>
  Effect.gen(function* () {
    yield* goTo('kepler_belt');
    yield* mineUntilFull();
    yield* goTo('kepler_base');
    yield* sell([{item_id: 'copper_ore'}]);
  });

// Re-arrive at the belt after a repair. Mine the *remainder* until full
// (do NOT re-flake: that would drop everything below 10 and loop).
const reBeltCycle = () =>
  Effect.gen(function* () {
    const p = yield* orient();
    if (p.hull < p.max_hull * 0.4) {
      const here = yield* goTo('sol_base');
      if (here.docked_at === null) {
        const taken = yield* service();
        if (taken.hull < p.max_hull * 0.4) return; // still too weak to fight
      }
    }
    const here = yield* goTo('kepler_belt');
    if (here.docked_at === null) {
      // Full: continue from the *current* hold, not a fresh 10.
      const p2 = yield* orient();
      if (p2.cargo_used >= p2.cargo_capacity) return;
    }
    return yield* mineUntilFull();
  });

const program = Effect.gen(function* () {
  const p0 = yield* orient();
  yield* note(`start @ ${p0.poi}, docked=${p0.docked_at ?? 'no'}`);

  // Head to kepler_belt; if pirates engage, wait them out and retry.
  yield* goTo('kepler_belt').pipe(Effect.retry({
    times: 12,
    schedule: Effect.gen(function* () {
      yield* disengage();
      return yield* Effect.sleep('1 second');
    }),
    while: e => e._tag === 'InBattle',
  }));

  // The haul: mine to full, fly to kepler_base, sell the copper.
  yield* haulCycle().pipe(Effect.retry({
    times: 16,
    schedule: Effect.gen(function* () {
      yield* disengage();
      return yield* Effect.sleep('1 second');
    }),
    while: e => e._tag === 'InBattle',
  }));

  // While we are docked at kepler_base (we just sold there):
  yield* service();
  yield* completeMissions().pipe(Effect.catchTag('NothingCompletable', () => Effect.void));

  // Re-arrive at the belt, accounting for hull; repair at base only if really hurt.
  yield* reBeltCycle().pipe(Effect.retry({
    times: 8,
    schedule: Effect.gen(function* () {
      yield* disengage();
      return yield* Effect.sleep('1 second');
    }),
    while: e => e._tag === 'InBattle',
  }));

  // Confirm the hold is actually full; if pirates keep winning we bail.
  const full = yield* orient();
  if (full.cargo_used < full.cargo_capacity) {
    const fresh = yield* mineUntilFull().pipe(Effect.retry({
      times: 5,
